import { useEffect, useState, useMemo, useRef } from 'react'

import { useQuery } from 'cozy-client'
import { useDataProxy } from 'cozy-dataproxy-lib'

import logger from '@/lib/logger'
import { buildRecentQuery } from '@/queries'

const useDataProxyRecents = () => {
  const [data, setData] = useState([])
  const [fetchStatus, setFetchStatus] = useState('loading')
  const [error, setError] = useState(null)
  const [useFallback, setUseFallback] = useState(false)
  const dataProxy = useDataProxy()

  // Memoize the query to avoid recreating it on every render
  const recentQuery = useMemo(() => buildRecentQuery(), [])
  const fallbackQueryResult = useQuery(
    recentQuery.definition,
    recentQuery.options
  )

  const fallbackStatus = fallbackQueryResult.fetchStatus
  const fallbackError = fallbackQueryResult.error
  const fallbackDataLength = useMemo(
    () => fallbackQueryResult.data?.length ?? 0,
    [fallbackQueryResult.data]
  )

  // Track previous values to avoid unnecessary updates
  const prevFallbackDataLengthRef = useRef(0)
  const prevFallbackStatusRef = useRef(null)
  const prevFallbackErrorRef = useRef(null)

  useEffect(() => {
    const fetchRecents = async () => {
      setFetchStatus('loading')
      setError(null)
      try {
        const data = await dataProxy.recents()
        setData(data || [])
        setFetchStatus('loaded')
        setUseFallback(false)
      } catch (err) {
        logger.error('Error fetching recents', err)
        setError(err)
        setUseFallback(true)
      }
    }

    if (dataProxy.dataProxyServicesAvailable) {
      fetchRecents()
    } else {
      setUseFallback(true)
    }
  }, [dataProxy])

  // Use fallback query result if dataProxy failed or is not available
  useEffect(() => {
    if (!useFallback) {
      return
    }

    const fallbackData = fallbackQueryResult.data

    // Compare array length and status to detect actual changes
    const hasDataChanged =
      fallbackData &&
      (fallbackDataLength !== prevFallbackDataLengthRef.current ||
        fallbackStatus !== prevFallbackStatusRef.current)

    // Only update if values have actually changed
    if (fallbackStatus === 'loaded' && hasDataChanged) {
      prevFallbackDataLengthRef.current = fallbackDataLength
      prevFallbackStatusRef.current = fallbackStatus
      setData(fallbackData || [])
      setFetchStatus('loaded')
      setError(null)
      return
    }

    if (
      fallbackStatus === 'error' &&
      (fallbackStatus !== prevFallbackStatusRef.current ||
        fallbackError !== prevFallbackErrorRef.current)
    ) {
      prevFallbackStatusRef.current = fallbackStatus
      prevFallbackErrorRef.current = fallbackError
      setFetchStatus('error')
      setError(fallbackError)
      return
    }

    if (
      fallbackStatus === 'loading' &&
      fallbackStatus !== prevFallbackStatusRef.current
    ) {
      prevFallbackStatusRef.current = fallbackStatus
      setFetchStatus('loading')
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [useFallback, fallbackDataLength, fallbackStatus, fallbackError])

  return { data, fetchStatus, error }
}

export default useDataProxyRecents
